/* The default letterhead mark, inlined as a data URI.
   A data URI rather than an image file so html2canvas can draw it into the PDF
   even when the app is opened straight off the disk, where a fetched image
   would taint the canvas and blank the letterhead. Replace it by uploading a
   logo in the app, or by swapping the string below.
   Per-state logos live in the state register instead. */
const DEFAULT_LOGO = "data:image/png;base64,";

/* The group mark, for the banner across the top of the opening screen.
   Inlined for the same reason as the letterhead logo: one file, no fetches. */
const BANNER_LOGO = "data:image/png;base64,";
